import java.util.Arrays;

public class StringArrayUtils {

    /**
     * Trim the elements of the given String array, calling <code>String.trim()</code> on each of them.
     * @param array the original String array
     * @return the resulting array (of the same size) with trimmed elements
     */
    public static String[] trimArrayElements(String[] array) {
        if (array == null) {
            return null;
        }

        String[] trimmedArray = new String[array.length];
        for (int i = 0; i < array.length; i++) {
            if (array[i] != null) {
                trimmedArray[i] = array[i].trim();
            } else {
                trimmedArray[i] = null;
            }
        }
        return trimmedArray;
    }

    public static void main(String[] args) {
        String[] inputArray = {"  hello ", " world  ", "  java  "};
        String[] resultArray = trimArrayElements(inputArray);
        System.out.println(Arrays.toString(resultArray));
    }
}

public class ArrayUtils {

    /**
     * <p>Checks whether two arrays are the same length, treating <code>null</code> arrays as length <code>0</code>.</p>
     * @param array1 the first array, may be <code>null</code>
     * @param array2 the second array, may be <code>null</code>
     * @return <code>true</code> if length of arrays matches, treating<code>null</code> as an empty array
     */
    public static boolean isSameLength(final byte[] array1, final byte[] array2) {
        int length1 = (array1 != null) ? array1.length : 0;
        int length2 = (array2 != null) ? array2.length : 0;
        return length1 == length2;
    }

    public static void main(String[] args) {
        // Test cases
        System.out.println(isSameLength(null, null)); // true
        System.out.println(isSameLength(new byte[0], new byte[0])); // true
        System.out.println(isSameLength(new byte[3], new byte[3])); // true
        System.out.println(isSameLength(new byte[3], new byte[2])); // false
        System.out.println(isSameLength(null, new byte[3])); // false
        System.out.println(isSameLength(new byte[3], null)); // false
    }
}

import java.util.Stack;

public class OutputFrame {
    private Stack<Integer> stack = new Stack<>();

    /**
     * Pops an abstract type from the output frame stack and returns its value.
     * @return the abstract type that has been popped from the output frame stack.
     */
    private int pop() {
        if (stack.isEmpty()) {
            throw new IllegalStateException("Stack is empty");
        }
        return stack.pop();
    }

    // Example usage
    public static void main(String[] args) {
        OutputFrame frame = new OutputFrame();
        frame.stack.push(10);
        frame.stack.push(20);
        System.out.println(frame.pop()); // Output: 20
        System.out.println(frame.pop()); // Output: 10
    }
}

import java.util.Arrays;

public class BooleanArrayConverter {

    /**
     * Converts an array of object Booleans to primitives.
     * This method returns <code>null</code> for a <code>null</code> input array.
     * @param array  a <code>Boolean</code> array, may be <code>null</code>
     * @return a <code>boolean</code> array, <code>null</code> if null array input
     * @throws NullPointerException if array content is <code>null</code>
     */
    public static boolean[] toPrimitive(final Boolean[] array) {
        if (array == null) {
            return null;
        }

        boolean[] primitiveArray = new boolean[array.length];
        for (int i = 0; i < array.length; i++) {
            if (array[i] == null) {
                throw new NullPointerException("Array content cannot be null");
            }
            primitiveArray[i] = array[i];
        }
        return primitiveArray;
    }

    public static void main(String[] args) {
        Boolean[] objectArray = {Boolean.TRUE, Boolean.FALSE, Boolean.TRUE};
        boolean[] primitiveArray = toPrimitive(objectArray);
        System.out.println(Arrays.toString(primitiveArray));
    }
}

