import java.util.Arrays;

public class ArrayUtils {
    /**
     * Return a hash code based on the contents of the specified array. If <code>array</code> is <code>null</code>, this method returns 0.
     * @param array the long array to obtain a hashcode
     * @return the long array's hashcode, which could be 0 if the array is null.
     */
    public static int nullSafeHashCode(long[] array) {
        if (array == null) {
            return 0;
        }
        int hash = 1;
        for (long element : array) {
            hash = 31 * hash + Long.hashCode(element);
        }
        return hash;
    }

    public static void main(String[] args) {
        long[] array1 = {1, 2, 3};
        long[] array2 = null;
        System.out.println("Hash code of array1: " + nullSafeHashCode(array1)); // Should print a non-zero hash code
        System.out.println("Hash code of array2: " + nullSafeHashCode(array2)); // Should print 0
    }
}

