        this.value = value;
        this.left = null;
        this.right = null;
    }
}

public class TreeUtils {

    /**
     * Performs a right node rotation.
     * @param node a node to rotate
     * @return a new parent of the {@code node}
     */
    private TreeNode<T> rotateRight(TreeNode<T> node) {
        if (node == null || node.left == null) {
            return node;
        }

        TreeNode<T> newRoot = node.left;
        node.left = newRoot.right;
        newRoot.right = node;

        return newRoot;
    }

    public static void main(String[] args) {
        // Example usage
        TreeUtils utils = new TreeUtils();
        TreeNode<Integer> root = new TreeNode<>(1);
        root.left = new TreeNode<>(2);
        root.left.left = new TreeNode<>(3);

        TreeNode<Integer> newRoot = utils.rotateRight(root);

        // Print the new root value to verify rotation
        System.out.println("New root value: " + newRoot.value);
    }
}

