import java.nio.file.Path;
import java.nio.file.Paths;

public class FileUtils {
    /**
     * Returns the index of the last directory separator character.
     * This method will handle a file in either Unix or Windows format.
     * The position of the last forward or backslash is returned.
     * The output will be the same irrespective of the machine that the code is running on.
     *
     * @param filename the filename to find the last path separator in, null returns -1
     * @return the index of the last separator character, or -1 if there is no such character
     */
    public static int indexOfLastSeparator(String filename) {
        if (filename == null) {
            return -1;
        }
        Path path = Paths.get(filename);
        return path.toString().lastIndexOf(Path.separator);
    }

    public static void main(String[] args) {
        // Test cases
        System.out.println(indexOfLastSeparator("/home/user/file.txt")); // Output: 11
        System.out.println(indexOfLastSeparator("C:\\Users\\User\\file.txt")); // Output: 18
        System.out.println(indexOfLastSeparator("file.txt")); // Output: -1
        System.out.println(indexOfLastSeparator(null)); // Output: -1
    }
}

import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class HeaderParser {

    /**
     * Skips bytes until the end of the current line.
     * @param headerPart The headers, which are being parsed.
     * @param end Index of the last byte, which has yet been processed.
     * @return Index of the \r\n sequence, which indicates end of line.
     */
    private int parseEndOfLine(String headerPart, int end) {
        Pattern pattern = Pattern.compile("(\\r?\\n)");
        Matcher matcher = pattern.matcher(headerPart.substring(end));
        if (matcher.find()) {
            return end + matcher.end();
        }
        return headerPart.length();
    }

    public static void main(String[] args) {
        HeaderParser parser = new HeaderParser();
        String headerPart = "Content-Type: text/plain\r\nContent-Length: 10\r\n";
        int end = 0;
        int eolIndex = parser.parseEndOfLine(headerPart, end);
        System.out.println("End of line index: " + eolIndex);
    }
}

