import org.jgrapht.Graph;
import org.jgrapht.graph.DefaultEdge;
import org.jgrapht.graph.SimpleGraph;
import org.jgrapht.isomorphism.IsomorphicGraphMapping;
import org.jgrapht.isomorphism.VF2SubgraphIsomorphismInspector;

import java.util.HashMap;
import java.util.Map;

public class GraphUtils {

    /**
     * Computes an identity automorphism (i.e. a self-mapping of a graph in which each vertex also maps to itself).
     * @param graph the input graph
     * @param <V> the graph vertex type
     * @param <E> the graph edge type
     * @return a mapping from graph to graph
     */
    public static <V, E> IsomorphicGraphMapping<V, E> identity(Graph<V, E> graph) {
        Map<V, V> mapping = new HashMap<>();
        for (V vertex : graph.vertexSet()) {
            mapping.put(vertex, vertex);
        }

        // Create a new graph to hold the identity mapping
        Graph<V, E> identityGraph = new SimpleGraph<>(DefaultEdge.class);
        for (V vertex : graph.vertexSet()) {
            identityGraph.addVertex(vertex);
        }
        for (E edge : graph.edgeSet()) {
            V source = graph.getEdgeSource(edge);
            V target = graph.getEdgeTarget(edge);
            identityGraph.addEdge(source, target);
        }

        // Use VF2 to find the isomorphism
        VF2SubgraphIsomorphismInspector<V, E> inspector = new VF2SubgraphIsomorphismInspector<>(graph, identityGraph);
        IsomorphicGraphMapping<V, E> isomorphism = inspector.getMapping();

        return isomorphism;
    }

    public static void main(String[] args) {
        // Example usage
        SimpleGraph<String, DefaultEdge> graph = new SimpleGraph<>(DefaultEdge.class);
        graph.addVertex("A");
        graph.addVertex("B");
        graph.addEdge("A", "B");

        IsomorphicGraphMapping<String, DefaultEdge> identityMapping = identity(graph);
        System.out.println("Identity Mapping: " + identityMapping);
    }
}

