}

import java.lang.reflect.ParameterizedType;
import java.lang.reflect.Type;
import java.lang.reflect.TypeVariable;

public class TypeResolver {

    /**
     * Resolves the arguments for the {@code genericType} using the type variable information for the {@code targetType}.
     * Returns {@code null} if {@code genericType} is not parameterized or if arguments cannot be resolved.
     */
    public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
        if (genericType instanceof ParameterizedType) {
            ParameterizedType parameterizedType = (ParameterizedType) genericType;
            Type[] actualTypeArguments = parameterizedType.getActualTypeArguments();
            Class<?>[] resolvedArguments = new Class<?>[actualTypeArguments.length];

            for (int i = 0; i < actualTypeArguments.length; i++) {
                resolvedArguments[i] = resolveType(actualTypeArguments[i], targetType);
            }

            return resolvedArguments;
        }
        return null;
    }

    private static Class<?> resolveType(Type type, Class<?> targetType) {
        if (type instanceof Class) {
            return (Class<?>) type;
        } else if (type instanceof TypeVariable) {
            TypeVariable<?> typeVariable = (TypeVariable<?>) type;
            Type genericSuperclass = targetType.getGenericSuperclass();
            if (genericSuperclass instanceof ParameterizedType) {
                ParameterizedType parameterizedType = (ParameterizedType) genericSuperclass;
                Class<?> rawType = (Class<?>) parameterizedType.getRawType();
                TypeVariable<?>[] typeParameters = rawType.getTypeParameters();
                for (int i = 0; i < typeParameters.length; i++) {
                    if (typeParameters[i].equals(typeVariable)) {
                        return (Class<?>) parameterizedType.getActualTypeArguments()[i];
                    }
                }
            }
        }
        return null;
    }

    public static void main(String[] args) {
        // Example usage
        class ExampleClass<T, U> {
        }

        ExampleClass<String, Integer> example = new ExampleClass<>();
        Class<?>[] arguments = resolveArguments(example.getClass().getGenericSuperclass(), ExampleClass.class);
        if (arguments != null) {
            for (Class<?> arg : arguments) {
                System.out.println(arg.getName());
            }
        }
    }
}

