public class ClassReader {
    private byte[] b;

    public ClassReader(byte[] b) {
        this.b = b;
    }

    /**
     * Reads a signed long value in this {@link ClassReader}. <i>This method is intended for {@link Attribute} sub classes, and is normally not needed by class generators or adapters.</i>
     * @param offset the start offset of the value to be read in this {@link ClassReader}.
     * @return the read value.
     */
    public long readLong(final int offset) {
        return ((b[offset] & 0xFFL) << 56) |
               ((b[offset + 1] & 0xFFL) << 48) |
               ((b[offset + 2] & 0xFFL) << 40) |
               ((b[offset + 3] & 0xFFL) << 32) |
               ((b[offset + 4] & 0xFFL) << 24) |
               ((b[offset + 5] & 0xFFL) << 16) |
               ((b[offset + 6] & 0xFFL) << 8) |
               (b[offset + 7] & 0xFFL);
    }

    public static void main(String[] args) {
        // Example usage
        byte[] classData = {0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x01}; // Example byte array representing a long value
        ClassReader reader = new ClassReader(classData);
        long value = reader.readLong(0);
        System.out.println("Read long value: " + value);
    }
}

