public class Buffer {
    private LoggingEvent[] buffer;
    private int capacity;
    private int size;

    public Buffer(int capacity) {
        this.capacity = capacity;
        this.buffer = new LoggingEvent[capacity];
        this.size = 0;
    }

    /**
     * Place a {@link LoggingEvent} in the buffer. If the buffer is full, the event is <b>silently dropped</b>.
     * It is the caller's responsibility to make sure that the buffer has free space.
     */
    public void put(LoggingEvent o) {
        if (size < capacity) {
            buffer[size++] = o;
        }
    }

    public static void main(String[] args) {
        // Example usage
        Buffer buffer = new Buffer(3);
        buffer.put(new LoggingEvent("FQCN", null, System.currentTimeMillis(), "Message 1", null));
        buffer.put(new LoggingEvent("FQCN", null, System.currentTimeMillis(), "Message 2", null));
        buffer.put(new LoggingEvent("FQCN", null, System.currentTimeMillis(), "Message 3", null));
