import java.time.LocalDate;
import java.time.format.DateTimeFormatter;

public class TimeBucketCompressor {

    static long compressTimeBucket(long timeBucket, int dayStep) {
        // Convert the time bucket long value to a LocalDate object
        String dateStr = String.valueOf(timeBucket);
        LocalDate date = LocalDate.parse(dateStr, DateTimeFormatter.BASIC_ISO_DATE);

        // Calculate the number of days to adjust based on the dayStep
        int daysToAdd = (dayStep - 1) / 2;

        // Adjust the date by adding the calculated number of days
        LocalDate adjustedDate = date.plusDays(daysToAdd);

        // If dayStep is odd, round to the nearest dayStep
        if (dayStep % 2 != 0) {
            LocalDate startOfMonth = adjustedDate.withDayOfMonth(1);
            int daysInMonth = startOfMonth.lengthOfMonth();
            int adjustedDay = (adjustedDate.getDayOfMonth() + daysToAdd) / dayStep * dayStep;
            adjustedDate = adjustedDate.withDayOfMonth(Math.min(adjustedDay, daysInMonth));
        }

        // Convert the adjusted date back to a long value
        return Long.parseLong(adjustedDate.format(DateTimeFormatter.BASIC_ISO_DATE));
    }

    public static void main(String[] args) {
        // Test cases
        System.out.println(compressTimeBucket(20000105, 11)); // Output: 20000101
        System.out.println(compressTimeBucket(20000115, 11)); // Output: 20000112
        System.out.println(compressTimeBucket(20000123, 11)); // Output: 20000123
    }
}

import java.nio.charset.StandardCharsets;

public class UTF8SizeCalculator {

    /**
     * Computes the size of the UTF-8 string beginning at the specified {@code index} with the specified {@code length}.
     */
    public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
        if (str == null || index < 0 || len < 0 || index + len > str.length()) {
            throw new IllegalArgumentException("Invalid input parameters");
        }

        int size = 0;
        for (int i = index; i < index + len; i++) {
            char ch = str.charAt(i);
            if (ch <= 0x7F) {
                size += 1;
            } else if (ch <= 0x7FF) {
                size += 2;
            } else if (Character.isHighSurrogate(ch)) {
                if (i + 1 < index + len && Character.isLowSurrogate(str.charAt(i + 1))) {
                    size += 4;
                    i++; // Skip the low surrogate
                } else {
                    throw new IllegalArgumentException("Invalid surrogate pair");
                }
            } else {
                size += 3;
            }
        }
        return size;
    }

    public static void main(String[] args) {
        String testString = "Hello, 世界!";
        int index = 0;
        int length = testString.length();
        int utf8Size = computeUTF8Size(testString, index, length);
        System.out.println("UTF-8 size: " + utf8Size);
    }
}

