public class Graph<V> {
    private Set<Edge<V>> edges;

    public Graph(Set<Edge<V>> edges) {
        this.edges = edges;
    }

    private Set<V> initVisibleVertices() {
        Set<V> visibleVertices = new HashSet<>();
        for (Edge<V> edge : edges) {
            visibleVertices.add(edge.getSource());
            visibleVertices.add(edge.getTarget());
        }
        return visibleVertices;
    }

    private static class Edge<V> {
        private V source;
        private V target;

        public Edge(V source, V target) {
            this.source = source;
            this.target = target;
        }

        public V getSource() {
            return source;
        }

        public V getTarget() {
            return target;
        }
    }

    public static void main(String[] args) {
        Set<Edge<String>> edges = new HashSet<>();
        edges.add(new Edge<>("A", "B"));
        edges.add(new Edge<>("B", "C"));
        edges.add(new Edge<>("C", "A"));

        Graph<String> graph = new Graph<>(edges);
        Set<String> visibleVertices = graph.initVisibleVertices();
        System.out.println(visibleVertices); // Output: [A, B, C]
    }
}

