public class TreeEdge {
    private TreeEdge next;
    private TreeEdge prev;

    public void removeFromTreeEdgeList() {
        if (prev != null) {
            prev.next = next;
        }
        if (next != null) {
            next.prev = prev;
        }
        prev = null;
        next = null;
    }

    public static void main(String[] args) {
        // Example usage
        TreeEdge edge1 = new TreeEdge();
        TreeEdge edge2 = new TreeEdge();
        TreeEdge edge3 = new TreeEdge();

        edge1.next = edge2;
        edge2.prev = edge1;
        edge2.next = edge3;
        edge3.prev = edge2;

        // Remove edge2 from the list
        edge2.removeFromTreeEdgeList();

        // Verify removal
        System.out.println(edge1.next == edge3); // true
        System.out.println(edge3.prev == edge1); // true
        System.out.println(edge2.next == null);  // true
        System.out.println(edge2.prev == null);  // true
    }
}

import java.util.Properties;

public class PropertySubstitutor {

    /**
     * Find the value corresponding to <code>key</code> in <code>props</code>. Then perform variable substitution on the found value.
     */
    public static String findAndSubst(String key, Properties props) {
        if (props == null || key == null) {
            return null;
        }

        String value = props.getProperty(key);
        if (value == null) {
            return null;
        }

        // Perform variable substitution
        return value.replaceAll("\\$\\{([^}]+)\\}", match -> props.getProperty(match.group(1), match.group(0)));
    }

    public static void main(String[] args) {
        Properties props = new Properties();
        props.setProperty("name", "John");
        props.setProperty("greeting", "Hello, ${name}!");

        String result = findAndSubst("greeting", props);
        System.out.println(result);  // Output: Hello, John!
    }
}

