    @Override
    public void write(final byte b[], final int off, final int len) throws IOException {
        if (b == null) {
            throw new NullPointerException();
        } else if ((off < 0) || (off > b.length) || (len < 0) ||
                   ((off + len) > b.length) || ((off + len) < 0)) {
            throw new IndexOutOfBoundsException();
        } else if (len == 0) {
            return;
        }
        int newcount = count + len;
        if (newcount > buf.length) {
            byte newbuf[] = new byte[Math.max(buf.length << 1, newcount)];
            System.arraycopy(buf, 0, newbuf, 0, count);
            buf = newbuf;
        }
        System.arraycopy(b, off, buf, count, len);
        count = newcount;
    }

    public static void main(String[] args) {
        CustomByteArrayOutputStream baos = new CustomByteArrayOutputStream();
        byte[] data = {1, 2, 3, 4, 5};
        try {
            baos.write(data, 1, 3);
            System.out.println("Written bytes: " + baos.toString());
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}

import java.util.Arrays;

public class ArrayUtils {
    /**
     * Swaps the two elements at the specified indices in the given array.
     * @param <V> the type of elements in the array
     * @param arr the array
     * @param i the index of the first element
     * @param j the index of the second element
     */
    public static final <V> void swap(V[] arr, int i, int j) {
        if (arr == null || i < 0 || j < 0 || i >= arr.length || j >= arr.length) {
            throw new IllegalArgumentException("Invalid indices or array");
        }
        V temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }

    public static void main(String[] args) {
        Integer[] array = {1, 2, 3, 4, 5};
        System.out.println("Before swap: " + Arrays.toString(array));
        swap(array, 1, 3);
        System.out.println("After swap: " + Arrays.toString(array));
    }
}

