import java.util.Set;

public class Graph<V, E> {
    private Map<V, Set<E>> index;

    public Graph() {
        this.index = new HashMap<>();
    }

    /**
     * Add an edge to the index.
     * @param sourceVertex the source vertex
     * @param targetVertex the target vertex
     * @param e the edge
     */
    protected void addToIndex(V sourceVertex, V targetVertex, E e) {
        if (!index.containsKey(sourceVertex)) {
            index.put(sourceVertex, new HashSet<>());
        }
        index.get(sourceVertex).add(e);

        if (!index.containsKey(targetVertex)) {
            index.put(targetVertex, new HashSet<>());
        }
        index.get(targetVertex).add(e);
    }

    public static void main(String[] args) {
        Graph<String, String> graph = new Graph<>();
        graph.addToIndex("A", "B", "edge1");
        graph.addToIndex("B", "C", "edge2");
        System.out.println(graph.index);
    }
}

