public class StringUtils {
    /**
     * Reverse of Introspector.decapitalize
     */
    public static String capitalize(String name) {
        if (name == null || name.isEmpty()) {
            return name;
        }
        if (name.length() > 1 && Character.isUpperCase(name.charAt(1))) {
            return name;
        }
        return Character.toUpperCase(name.charAt(0)) + name.substring(1);
    }

    public static void main(String[] args) {
        // Test cases
        System.out.println(capitalize("hello")); // Output: Hello
        System.out.println(capitalize("HELLO")); // Output: HELLO
        System.out.println(capitalize("hELLO")); // Output: HELLO
        System.out.println(capitalize(""));      // Output: 
        System.out.println(capitalize(null));    // Output: null
    }
}

import java.io.DataOutput;
import java.io.IOException;

public class LinkedBufferWriter {

    public static int writeTo(final DataOutput out, LinkedBuffer node) throws IOException {
        int totalSize = 0;
        while (node != null) {
            out.write(node.getData(), node.getStart(), node.getLength());
            totalSize += node.getLength();
            node = node.getNext();
        }
        return totalSize;
    }

    // Assuming LinkedBuffer is a class with the following structure:
    static class LinkedBuffer {
        private byte[] data;
        private int start;
        private int length;
        private LinkedBuffer next;

        public LinkedBuffer(byte[] data, int start, int length, LinkedBuffer next) {
            this.data = data;
            this.start = start;
            this.length = length;
            this.next = next;
        }

        public byte[] getData() {
            return data;
        }

        public int getStart() {
            return start;
        }

        public int getLength() {
            return length;
        }

        public LinkedBuffer getNext() {
            return next;
        }
    }

    public static void main(String[] args) {
        // Example usage
        LinkedBuffer buffer = new LinkedBuffer("Hello".getBytes(), 0, 5, null);
        try {
            int size = writeTo(System.out, buffer);
            System.out.println("Total size written: " + size);
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}

