import java.lang.Character;

public class Converter {
    /**
     * <p>Convert the input object into a java.lang.Character.</p>
     * @param type Data type to which this value should be converted.
     * @param value The input value to be converted.
     * @return The converted value.
     * @throws Exception if conversion cannot be performed successfully
     * @since 1.8.0
     */
    @Override
    protected Object convertToType(final Class<?> type, final Object value) throws Exception {
        if (type.equals(Character.class)) {
            if (value instanceof Character) {
                return value;
            } else if (value instanceof String) {
                String strValue = (String) value;
                if (strValue.length() == 1) {
                    return strValue.charAt(0);
                } else {
                    throw new Exception("Cannot convert string to Character: " + value);
                }
            } else {
                throw new Exception("Unsupported conversion from " + value.getClass() + " to Character");
            }
        } else {
            throw new Exception("Unsupported conversion to " + type);
        }
    }

    public static void main(String[] args) {
        Converter converter = new Converter();
        try {
            System.out.println(converter.convertToType(Character.class, 'A')); // Output: A
            System.out.println(converter.convertToType(Character.class, "B")); // Output: B
            System.out.println(converter.convertToType(Character.class, "AB")); // Throws Exception
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}

import java.util.List;

public class StringUtils {
    /**
     * Case in-sensitive Checks if the String contains any character in the given set of string.
     */
    public static boolean containsAnyIgnoreCase(String str, List<String> searchStrArray) {
        if (str == null || searchStrArray == null) {
            return false;
        }

        for (String searchStr : searchStrArray) {
            if (searchStr != null && str.toLowerCase().contains(searchStr.toLowerCase())) {
                return true;
