import java.util.stream.IntStream;

public class PrimeUtil {
    /**
     * Returns a prime number which is >= desiredCapacity and very close to desiredCapacity (within 11% if desiredCapacity >= 1000).
     * @param desiredCapacity the capacity desired by the user.
     * @return the capacity which should be used for a hashtable.
     */
    public static int nextPrime(int desiredCapacity) {
        if (desiredCapacity < 2) {
            return 2;
        }

        int upperBound = desiredCapacity;
        if (desiredCapacity >= 1000) {
            upperBound = (int) (desiredCapacity * 1.11);
        }

        return IntStream.rangeClosed(desiredCapacity, upperBound)
                        .filter(PrimeUtil::isPrime)
                        .findFirst()
                        .orElse(desiredCapacity);
    }

    private static boolean isPrime(int number) {
        if (number <= 1) {
            return false;
        }
        if (number <= 3) {
            return true;
        }
        if (number % 2 == 0 || number % 3 == 0) {
            return false;
        }
        for (int i = 5; i * i <= number; i += 6) {
            if (number % i == 0 || number % (i + 2) == 0) {
                return false;
            }
        }
        return true;
    }

    public static void main(String[] args) {
        System.out.println(nextPrime(1000)); // Example usage
    }
}

