public class DigitValue {

    private static int digitValue(final char c) {
        if (Character.isDigit(c)) {
            return c - '0';
        } else if (c >= 'a' && c <= 'z') {
            return c - 'a' + 10;
        } else if (c >= 'A' && c <= 'Z') {
            return c - 'A' + 10;
        } else {
            return -1; // Invalid character
        }
    }

    public static void main(String[] args) {
