import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class StringUnescaper {

    /**
     * <p>Unescapes any Java literals found in the <code>String</code>. For example, it will turn a sequence of <code>'\'</code> and <code>'n'</code> into a newline character, unless the <code>'\'</code> is preceded by another <code>'\'</code>.</p>
     * @param str the <code>String</code> to unescape, may be null
     * @return a new unescaped <code>String</code>, <code>null</code> if null string input
     */
    public static String unescapeJava(String str) throws Exception {
        if (str == null) {
            return null;
        }

        StringBuilder sb = new StringBuilder();
        int i = 0;
        int len = str.length();

        while (i < len) {
            char c = str.charAt(i);
            if (c == '\\') {
                if (i + 1 < len) {
                    char nextChar = str.charAt(i + 1);
                    switch (nextChar) {
                        case 'n':
                            sb.append('\n');
                            break;
                        case 't':
                            sb.append('\t');
                            break;
                        case 'r':
                            sb.append('\r');
                            break;
                        case 'f':
                            sb.append('\f');
                            break;
                        case 'b':
                            sb.append('\b');
                            break;
                        case '"':
                            sb.append('"');
                            break;
                        case '\'':
                            sb.append('\'');
                            break;
                        case '\\':
                            sb.append('\\');
                            break;
                        default:
                            throw new Exception("Invalid escape sequence: \\" + nextChar);
                    }
                    i += 2;
                } else {
                    throw new Exception("Invalid escape sequence at end of string");
                }
            } else {
                sb.append(c);
                i++;
            }
        }

        return sb.toString();
    }

    public static void main(String[] args) {
        try {
            System.out.println(unescapeJava("Hello\\nWorld\\tThis\\'s a test\\\\string."));
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}

import java.nio.charset.Charset;
import java.nio.charset.StandardCharsets;

public class CharsetTranslator {

    /**
     * Translate a MIME standard character set name into the Java equivalent.
     * @param charset The MIME standard name.
     * @return The Java equivalent for this name.
     */
    private static String javaCharset(String charset) {
        if (charset == null) {
            return null;
        }

        charset = charset.trim().toLowerCase();

        switch (charset) {
            case "us-ascii":
                return StandardCharsets.US_ASCII.name();
            case "iso-8859-1":
                return StandardCharsets.ISO_8859_1.name();
            case "utf-8":
                return StandardCharsets.UTF_8.name();
            case "utf-16":
                return StandardCharsets.UTF_16.name();
            case "utf-16be":
                return StandardCharsets.UTF_16BE.name();
            case "utf-16le":
                return StandardCharsets.UTF_16LE.name();
            default:
                try {
                    if (Charset.isSupported(charset)) {
                        return charset;
                    }
                } catch (Exception e) {
                    // Ignore and return null if charset is not supported
                }
                return null;
        }
    }

    public static void main(String[] args) {
        // Example usage
        System.out.println(javaCharset("UTF-8")); // Output: UTF-8
        System.out.println(javaCharset("iso-8859-1")); // Output: ISO-8859-1
        System.out.println(javaCharset("unknown")); // Output: null
    }
}

