import java.util.ListIterator;

public class ListNode<E> implements ListIterator<E> {
    private ListNode<E> previous;
    private ListNode<E> next;
    private E element;

    public ListNode(E element) {
        this.element = element;
    }

    @Override
    public ListNode<E> previousNode() {
        return previous;
    }

    @Override
    public boolean hasPrevious() {
        return previous != null;
    }

    @Override
    public E previous() {
        if (!hasPrevious()) {
            throw new NoSuchElementException();
        }
        ListNode<E> current = previous;
        previous = previous.previous;
        return current.element;
    }

    @Override
    public int previousIndex() {
        return hasPrevious() ? previousIndex() - 1 : -1;
    }

    @Override
    public void set(E e) {
        throw new UnsupportedOperationException();
    }

    @Override
    public void add(E e) {
        throw new UnsupportedOperationException();
    }

    @Override
    public boolean hasNext() {
        return next != null;
    }

    @Override
    public E next() {
        if (!hasNext()) {
            throw new NoSuchElementException();
        }
        ListNode<E> current = next;
        next = next.next;
        return current.element;
    }

    @Override
    public int nextIndex() {
        return hasNext() ? nextIndex() + 1 : -1;
    }

    public void setPrevious(ListNode<E> previous) {
        this.previous = previous;
    }

    public void setNext(ListNode<E> next) {
        this.next = next;
    }
}

