import java.util.ArrayList;
import java.util.List;

class Category {
    private String name;
    private boolean isActive;
    private List<Category> children;

    public Category(String name, boolean isActive) {
        this.name = name;
        this.isActive = isActive;
        this.children = new ArrayList<>();
    }

    public boolean isActive() {
        return isActive;
    }

    public List<Category> getChildren() {
        return children;
    }

    public void addChild(Category child) {
        children.add(child);
    }

    public int removeUnusedNodes() {
        return removeUnusedNodesHelper(this);
    }

    private int removeUnusedNodesHelper(Category category) {
        if (!category.isActive()) {
            return 1; // This node is inactive, count it for removal
        }

        List<Category> toRemove = new ArrayList<>();
        for (Category child : category.getChildren()) {
            int removedCount = removeUnusedNodesHelper(child);
            if (removedCount > 0) {
                toRemove.add(child);
            }
        }

        category.getChildren().removeAll(toRemove);
        return toRemove.size();
    }
}

public class Main {
    public static void main(String[] args) {
        // Example usage
        Category root = new Category("Root", true);
        Category child1 = new Category("Child1", false);
        Category child2 = new Category("Child2", true);
        Category grandChild1 = new Category("GrandChild1", false);
        Category grandChild2 = new Category("GrandChild2", true);

        root.addChild(child1);
        root.addChild(child2);
        child2.addChild(grandChild1);
        child2.addChild(grandChild2);

        int removedNodes = root.removeUnusedNodes();
        System.out.println("Removed " + removedNodes + " inactive nodes.");
    }
}

