import java.util.ArrayList;
import java.util.Enumeration;
import java.util.List;

public class EnumerationUtils {

    /**
     * Copy the given Enumeration into a String array. The Enumeration must contain String elements only.
     * @param enumeration the Enumeration to copy
     * @return the String array (<code>null</code> if the passed-in Enumeration was <code>null</code>)
     */
    public static String[] toStringArray(Enumeration<String> enumeration) {
        if (enumeration == null) {
            return null;
        }

        List<String> list = new ArrayList<>();
        while (enumeration.hasMoreElements()) {
            list.add(enumeration.nextElement());
        }

        return list.toArray(new String[0]);
    }

    public static void main(String[] args) {
        // Example usage
        Enumeration<String> enumeration = new Enumeration<String>() {
            private final String[] elements = {"apple", "banana", "cherry"};
            private int index = 0;

            @Override
            public boolean hasMoreElements() {
                return index < elements.length;
            }

            @Override
            public String nextElement() {
                if (!hasMoreElements()) {
                    throw new java.util.NoSuchElementException();
                }
                return elements[index++];
            }
        };

        String[] array = toStringArray(enumeration);
        for (String s : array) {
            System.out.println(s);
        }
    }
}

import java.util.Arrays;

public class ByteVector {
    private byte[] data;
    private int size;

    public ByteVector() {
        this.data = new byte[16];
        this.size = 0;
    }

    public ByteVector putByteArray(final byte[] byteArrayValue, final int byteOffset, final int byteLength) {
        if (byteArrayValue == null) {
            ensureCapacity(byteLength);
            Arrays.fill(data, size, size + byteLength, (byte) 0);
        } else {
            ensureCapacity(byteLength);
            System.arraycopy(byteArrayValue, byteOffset, data, size, byteLength);
        }
        size += byteLength;
        return this;
    }

    private void ensureCapacity(int additionalCapacity) {
        int newCapacity = Math.max(data.length, size + additionalCapacity);
        if (newCapacity > data.length) {
            byte[] newData = new byte[newCapacity];
            System.arraycopy(data, 0, newData, 0, size);
            data = newData;
        }
    }

    public byte[] toArray() {
        return Arrays.copyOf(data, size);
    }

    public int size() {
        return size;
    }

    public static void main(String[] args) {
        ByteVector byteVector = new ByteVector();
        byte[] byteArray = {1, 2, 3, 4, 5};
        byteVector.putByteArray(byteArray, 1, 3);
        byteVector.putByteArray(null, 0, 2);
        System.out.println(Arrays.toString(byteVector.toArray()));
    }
}

