public class ShardingKeyChecker {

    private List<Integer> shardingKeyIndices;

    public ShardingKeyChecker(List<Integer> shardingKeyIndices) {
        this.shardingKeyIndices = shardingKeyIndices;
    }

    /**
     * @param modelName model name of the entity
     * @throws IllegalStateException if sharding key indices are not continuous
     */
    private void check(String modelName) throws IllegalStateException {
        if (shardingKeyIndices == null || shardingKeyIndices.isEmpty()) {
            throw new IllegalStateException("Sharding key indices cannot be null or empty for model: " + modelName);
        }

        for (int i = 0; i < shardingKeyIndices.size() - 1; i++) {
            if (shardingKeyIndices.get(i) + 1 != shardingKeyIndices.get(i + 1)) {
                throw new IllegalStateException("Sharding key indices are not continuous for model: " + modelName);
            }
        }
    }

    public static void main(String[] args) {
        ShardingKeyChecker checker = new ShardingKeyChecker(List.of(0, 1, 2, 3));
        try {
            checker.check("TestModel");
            System.out.println("Sharding key indices are continuous.");
        } catch (IllegalStateException e) {
            System.err.println(e.getMessage());
        }
    }
}

import java.io.IOException;
import java.io.InputStream;

public class ByteReader {
    private InputStream inputStream;
    private byte[] buffer;
    private int bufferSize;
    private int bufferPosition;

    public ByteReader(InputStream inputStream, int bufferSize) {
        this.inputStream = inputStream;
        this.bufferSize = bufferSize;
        this.buffer = new byte[bufferSize];
        this.bufferPosition = bufferSize; // Initialize to bufferSize to trigger a refill on the first read
    }

    public byte readByte() throws IOException {
        if (bufferPosition >= bufferSize) {
            refillBuffer();
        }
        if (bufferPosition >= bufferSize) {
            throw new IOException("No more data available");
        }
        return buffer[bufferPosition++];
    }

    private void refillBuffer() throws IOException {
        bufferPosition = 0;
        int bytesRead = inputStream.read(buffer);
        if (bytesRead == -1) {
            bufferPosition = bufferSize; // Mark as empty
        } else if (bytesRead < bufferSize) {
            // Shift the remaining bytes to the beginning of the buffer
            System.arraycopy(buffer, bytesRead, buffer, 0, bufferSize - bytesRead);
            bufferPosition = bufferSize - bytesRead;
        }
    }
}

