public class Graph {
    private Map<V, Map<V, Double>> adjacencyList;

    public Graph() {
        this.adjacencyList = new HashMap<>();
    }

    public void addVertex(V vertex) {
        adjacencyList.putIfAbsent(vertex, new HashMap<>());
    }

    public void addEdge(V from, V to, double weight) {
        adjacencyList.get(from).put(to, weight);
    }

    public double vertexWeight(V v) {
        double sum = 0.0;
        for (Map.Entry<V, Map<V, Double>> entry : adjacencyList.entrySet()) {
