public class Logger {
    private Appender[] appenders;

    public Logger(Appender[] appenders) {
        this.appenders = appenders;
    }

    public int appendLoopOnAppenders(LoggingEvent event) {
        if (appenders == null) {
            return 0;
        }

        int count = 0;
        for (Appender appender : appenders) {
            if (appender != null) {
                appender.doAppend(event);
                count++;
            }
        }
        return count;
    }
}

