import java.util.HashMap;
import java.util.Map;

public class SymbolTable {
    private Map<String, Integer> constantPool;
    private int nextIndex;

    public SymbolTable() {
        constantPool = new HashMap<>();
        nextIndex = 1; // Index 0 is reserved
    }

    /**
     * Adds a CONSTANT_NameAndType_info to the constant pool of this symbol table. Does nothing if the constant pool already contains a similar item.
     * @param name a field or method name.
     * @param descriptor a field or method descriptor.
     * @return a new or already existing Symbol with the given value.
     */
    public int addConstantNameAndType(final String name, final String descriptor) {
        String key = name + "#" + descriptor;
        if (constantPool.containsKey(key)) {
            return constantPool.get(key);
        }
        constantPool.put(key, nextIndex);
        return nextIndex++;
    }

    public static void main(String[] args) {
        SymbolTable symbolTable = new SymbolTable();
        int index1 = symbolTable.addConstantNameAndType("fieldName", "I");
        int index2 = symbolTable.addConstantNameAndType("methodName", "()V");
        int index3 = symbolTable.addConstantNameAndType("fieldName", "I");

        System.out.println("Index of fieldName (I): " + index1);
        System.out.println("Index of methodName (()V): " + index2);
        System.out.println("Index of fieldName (I) (again): " + index3);
    }
}

