public class ArrayConcatenator {

    /**
     * Concatenate the given String arrays into one, with overlapping array elements included twice.
     * The order of elements in the original arrays is preserved.
     * @param array1 the first array (can be <code>null</code>)
     * @param array2 the second array (can be <code>null</code>)
     * @return the new array (<code>null</code> if both given arrays were <code>null</code>)
     */
    public static String[] concatenateStringArrays(String[] array1, String[] array2) {
        if (array1 == null && array2 == null) {
            return null;
        }

        int length1 = (array1 != null) ? array1.length : 0;
        int length2 = (array2 != null) ? array2.length : 0;
        String[] result = new String[length1 + length2];

        if (array1 != null) {
            System.arraycopy(array1, 0, result, 0, length1);
        }

        if (array2 != null) {
            System.arraycopy(array2, 0, result, length1, length2);
        }

        return result;
    }

    public static void main(String[] args) {
        String[] array1 = {"a", "b", "c"};
        String[] array2 = {"d", "e", "f"};
        String[] result = concatenateStringArrays(array1, array2);
        System.out.println(Arrays.toString(result)); // Output: [a, b, c, d, e, f]

        String[] array3 = null;
        String[] array4 = {"g", "h"};
        String[] result2 = concatenateStringArrays(array3, array4);
        System.out.println(Arrays.toString(result2)); // Output: [g, h]

        String[] array5 = {"i", "j"};
        String[] array6 = null;
        String[] result3 = concatenateStringArrays(array5, array6);
        System.out.println(Arrays.toString(result3)); // Output: [i, j]

        String[] array7 = null;
        String[] array8 = null;
        String[] result4 = concatenateStringArrays(array7, array8);
        System.out.println(Arrays.toString(result4)); // Output: null
    }
}

import java.util.List;
import java.util.Set;
import java.util.HashSet;

private void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
    // Create a new bucket for label 0 if it doesn't exist
    if (bucketsByLabel.size() <= 0) {
        bucketsByLabel.add(new HashSet<>());
    }

    // Move all vertices from the bucket with label minLabel to the bucket with label 0
    Set<Integer> minLabelBucket = bucketsByLabel.get(minLabel);
    Set<Integer> zeroLabelBucket = bucketsByLabel.get(0);
    for (Integer vertex : minLabelBucket) {
        zeroLabelBucket.add(vertex);
        labels.set(vertex, 0);
    }

    // Clear the bucket with label minLabel
    minLabelBucket.clear();
}

