import java.util.regex.Pattern;

public class SubstringCounter {

    /**
     * Returns the number of occurrences the substring {@code sub} appears in string {@code str}.
     * @param str string to search in. Return 0 if this is null.
     * @param sub string to search for. Return 0 if this is null.
     * @return the number of occurrences the substring {@code sub} appears in string {@code str}.
     */
    public static int countOccurrencesOf(String str, String sub) {
        if (str == null || sub == null || sub.isEmpty()) {
            return 0;
        }

        int count = 0;
        Pattern pattern = Pattern.compile(Pattern.quote(sub));
        Matcher matcher = pattern.matcher(str);

        while (matcher.find()) {
            count++;
        }

        return count;
    }

    public static void main(String[] args) {
        // Example usage
        System.out.println(countOccurrencesOf("hello world, hello universe", "hello")); // Output: 2
        System.out.println(countOccurrencesOf("aaaa", "aa")); // Output: 3
        System.out.println(countOccurrencesOf(null, "test")); // Output: 0
        System.out.println(countOccurrencesOf("test", null)); // Output: 0
        System.out.println(countOccurrencesOf("test", "")); // Output: 0
    }
}

