public class FrameStack {
    private Stack<Object> outputFrameStack = new Stack<>();

    /**
     * Pops the given number of abstract types from the output frame stack.
     * @param elements the number of abstract types that must be popped.
     */
    private void pop(final int elements) {
        for (int i = 0; i < elements; i++) {
            if (!outputFrameStack.isEmpty()) {
                outputFrameStack.pop();
            } else {
                throw new IllegalStateException("Not enough elements to pop from the stack.");
            }
        }
    }

    public static void main(String[] args) {
        FrameStack frameStack = new FrameStack();
        // Example usage
        frameStack.outputFrameStack.push("Type1");
        frameStack.outputFrameStack.push("Type2");
        frameStack.outputFrameStack.push("Type3");

        frameStack.pop(2);

        System.out.println(frameStack.outputFrameStack); // Output should be [Type1]
    }
}

