import java.util.NoSuchElementException;

class ListNodeImpl<E> {
    E data;
    ListNodeImpl<E> next;
    ListNodeImpl<E> prev;

    ListNodeImpl(E data) {
        this.data = data;
    }
}

public class LinkedList<E> {
    private ListNodeImpl<E> head;
    private ListNodeImpl<E> tail;
    private int size;

    public boolean unlink(ListNodeImpl<E> node) {
        if (node == null) {
            throw new NoSuchElementException("Node to unlink cannot be null");
        }

        if (node.prev != null) {
            node.prev.next = node.next;
        } else {
            head = node.next;
        }

        if (node.next != null) {
            node.next.prev = node.prev;
        } else {
            tail = node.prev;
        }

        node.next = null;
        node.prev = null;
        size--;
        return true;
    }

    public static void main(String[] args) {
        LinkedList<String> list = new LinkedList<>();
        ListNodeImpl<String> node1 = new ListNodeImpl<>("A");
        ListNodeImpl<String> node2 = new ListNodeImpl<>("B");
        ListNodeImpl<String> node3 = new ListNodeImpl<>("C");

        list.head = node1;
        node1.next = node2;
        node2.prev = node1;
        node2.next = node3;
        node3.prev = node2;
        list.tail = node3;
        list.size = 3;

        list.unlink(node2);

        // Verify the list after unlinking
        System.out.println("Head: " + list.head.data); // Should print "A"
        System.out.println("Tail: " + list.tail.data); // Should print "C"
        System.out.println("Size: " + list.size); // Should print "2"
    }
}

