    }
}

class DoublyLinkedList<E> {
    private ListNode<E> head;
    private ListNode<E> tail;
    private int size;

    public DoublyLinkedList() {
        head = null;
        tail = null;
        size = 0;
    }

    public void addListNode(ListNode<E> node) {
        if (node == null) {
            throw new IllegalArgumentException("Node cannot be null");
        }
        if (tail != null) {
            tail.next = node;
            node.prev = tail;
            tail = node;
        } else {
            head = tail = node;
        }
        size++;
    }

    public ListNode<E> removeListNode(ListNode<E> node) {
        if (node == null) {
            throw new IllegalArgumentException("Node cannot be null");
        }
        if (node.prev != null) {
            node.prev.next = node.next;
        } else {
            head = node.next;
        }
        if (node.next != null) {
            node.next.prev = node.prev;
        } else {
            tail = node.prev;
        }
        size--;
        return node;
    }

    public int size() {
        return size;
    }

    private void moveAllListNodes(DoublyLinkedList<E> list) {
        if (list == null) {
            throw new IllegalArgumentException("List cannot be null");
        }
        while (list.head != null) {
            ListNode<E> node = list.removeListNode(list.head);
            addListNode(node);
        }
    }
}

