import javax.swing.*;
import java.awt.*;

public class TableUtils {

    /**
     * Selects the specified row in the specified JTable and scrolls the specified JScrollPane to the newly selected row.
     * More importantly, the call to repaint() is delayed long enough to have the table properly paint the newly selected row which may be offscreen.
     *
     * @param row   the row index to select
     * @param table the JTable to select the row in
     * @param pane  the JScrollPane containing the JTable
     */
    public static void selectRow(int row, JTable table, JScrollPane pane) {
        if (row >= 0 && row < table.getRowCount()) {
            table.setRowSelectionInterval(row, row);
            SwingUtilities.invokeLater(() -> {
                Rectangle rect = table.getCellRect(row, 0, true);
                pane.getViewport().scrollRectToVisible(rect);
                table.repaint();
            });
        }
    }

    public static void main(String[] args) {
        // Example usage
        JFrame frame = new JFrame("Table Example");
        frame.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);

        String[] columnNames = {"Column 1", "Column 2"};
        Object[][] data = {
            {"Row 1", "Data 1"},
            {"Row 2", "Data 2"},
            {"Row 3", "Data 3"}
        };

        JTable table = new JTable(data, columnNames);
        JScrollPane scrollPane = new JScrollPane(table);

        frame.add(scrollPane);
        frame.setSize(300, 200);
        frame.setVisible(true);

        // Select row 1 and scroll to it
        selectRow(1, table, scrollPane);
    }
}

import java.util.Arrays;

public class ByteVector {
    private byte[] data;
    private int size;

    public ByteVector() {
        this.data = new byte[16];
        this.size = 0;
    }

    public ByteVector putInt(final int intValue) {
        ensureCapacity(size + 4);
        data[size++] = (byte) (intValue >>> 24);
        data[size++] = (byte) (intValue >>> 16);
        data[size++] = (byte) (intValue >>> 8);
        data[size++] = (byte) intValue;
        return this;
    }

    private void ensureCapacity(int minCapacity) {
        if (minCapacity > data.length) {
            int newCapacity = Math.max(data.length << 1, minCapacity);
            data = Arrays.copyOf(data, newCapacity);
        }
    }

    public byte[] toArray() {
        return Arrays.copyOf(data, size);
    }

    public static void main(String[] args) {
        ByteVector byteVector = new ByteVector();
        byteVector.putInt(123456789);
        byte[] result = byteVector.toArray();
        for (byte b : result) {
            System.out.printf("%02X ", b);
        }
    }
}

import java.util.Arrays;

public class ArrayUtils {
    /**
     * Compares <code>count</code> first bytes in the arrays <code>a</code> and <code>b</code>.
     * @param a     The first array to compare.
     * @param b     The second array to compare.
     * @param count How many bytes should be compared.
     * @return <code>true</code> if <code>count</code> first bytes in arrays <code>a</code> and <code>b</code> are equal.
     */
    public static boolean arrayequals(byte[] a, byte[] b, int count) {
        if (a == null || b == null || count < 0) {
            return false;
        }
        if (count == 0) {
            return true;
        }
        if (a.length < count || b.length < count) {
            return false;
        }
        for (int i = 0; i < count; i++) {
            if (a[i] != b[i]) {
                return false;
            }
        }
        return true;
    }

    public static void main(String[] args) {
        byte[] array1 = {1, 2, 3, 4, 5};
        byte[] array2 = {1, 2, 3, 4, 6};
        int count = 4;
        System.out.println(arrayequals(array1, array2, count)); // Output: true

        count = 5;
        System.out.println(arrayequals(array1, array2, count)); // Output: false
    }
}

import java.util.StringTokenizer;

public class NameAbbreviator {

    /**
     * Abbreviate name.
     * @param buf buffer to append abbreviation.
     * @param nameStart start of name to abbreviate.
     */
    public void abbreviate(final int nameStart, final StringBuffer buf) {
        // Assuming the name is a space-separated string
        String name = buf.substring(nameStart);
        StringTokenizer tokenizer = new StringTokenizer(name);

        while (tokenizer.hasMoreTokens()) {
            String token = tokenizer.nextToken();
            if (tokenizer.hasMoreTokens()) {
                buf.append(token.charAt(0)).append(".");
            } else {
                buf.append(token);
            }
        }
    }

    public static void main(String[] args) {
        StringBuffer buf = new StringBuffer("John Doe Smith");
        NameAbbreviator abbreviator = new NameAbbreviator();
        abbreviator.abbreviate(0, buf);
        System.out.println(buf.toString()); // Output: J.D.Smith
    }
}

