private static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    for (V vertex : vertices) {
        for (V otherVertex : vertices) {
            if (!vertex.equals(otherVertex) && !graph.containsEdge(vertex, otherVertex)) {
                return false;
            }
        }
    }
    return true;
}

import java.util.ArrayList;
import java.util.List;

public class LowerBoundCalculator {

    /**
     * Finds a maximum lower bound for every key.
     * @param keys list of keys.
     * @return the computed key lower bounds.
     */
    private List<Integer> computeLowerBounds(List<Integer> keys) {
        List<Integer> lowerBounds = new ArrayList<>();
        if (keys == null || keys.isEmpty()) {
            return lowerBounds;
        }

        int currentLowerBound = Integer.MIN_VALUE;
        for (int key : keys) {
            if (key > currentLowerBound) {
                currentLowerBound = key;
            }
            lowerBounds.add(currentLowerBound);
        }

        return lowerBounds;
    }

    public static void main(String[] args) {
        LowerBoundCalculator calculator = new LowerBoundCalculator();
        List<Integer> keys = List.of(3, 1, 4, 1, 5, 9, 2, 6, 5, 3, 5);
        List<Integer> lowerBounds = calculator.computeLowerBounds(keys);
        System.out.println(lowerBounds);
    }
}

import java.util.Stack;

public class Frame {
    private Stack<String> outputFrameStack;

    public Frame() {
        this.outputFrameStack = new Stack<>();
    }

    /**
     * Pops as many abstract types from the output frame stack as described by the given descriptor.
     * @param descriptor a type or method descriptor (in which case its argument types are popped).
     */
    private void pop(final String descriptor) {
        if (descriptor.startsWith("(")) {
            // It's a method descriptor, extract argument types
            int endIndex = descriptor.indexOf(')');
            String arguments = descriptor.substring(1, endIndex);
            popTypes(arguments);
        } else {
            // It's a type descriptor
            popTypes(descriptor);
        }
    }

    private void popTypes(String types) {
        for (char type : types.toCharArray()) {
            switch (type) {
                case 'B': // byte
                case 'C': // char
                case 'I': // int
                case 'S': // short
                case 'Z': // boolean
                case 'F': // float
                case 'J': // long
                case 'D': // double
                    outputFrameStack.pop();
                    break;
                case 'L': // object
                    // Find the end of the object descriptor
                    int endIndex = types.indexOf(';', types.indexOf(type));
                    outputFrameStack.pop();
                    break;
                case '[': // array
                    // Skip the array dimensions and pop the base type
                    int baseTypeIndex = types.indexOf(';', types.indexOf(type));
                    if (baseTypeIndex == -1) {
                        baseTypeIndex = types.length();
                    }
                    popTypes(types.substring(typeIndex, baseTypeIndex));
                    break;
                default:
                    throw new IllegalArgumentException("Unknown type descriptor: " + type);
            }
        }
    }

    public static void main(String[] args) {
        Frame frame = new Frame();
        // Example usage
        frame.outputFrameStack.push("I"); // int
        frame.outputFrameStack.push("Ljava/lang/String;"); // String
        frame.pop("(I)Ljava/lang/String;"); // Method descriptor
        System.out.println(frame.outputFrameStack); // Should be empty
    }
}

