import java.util.ArrayList;
import java.util.List;

public class UpperBoundCalculator {

    /**
     * Finds a minimum lower bound for every key.
     * @param keys a list of keys.
     * @return the computed key upper bound.
     */
    private List<Integer> computeUpperBounds(List<Integer> keys) {
        List<Integer> upperBounds = new ArrayList<>();
        if (keys == null || keys.isEmpty()) {
            return upperBounds;
        }

        int minKey = Integer.MAX_VALUE;
        for (Integer key : keys) {
            if (key < minKey) {
                minKey = key;
            }
        }

        for (Integer key : keys) {
            upperBounds.add(key - minKey);
        }

        return upperBounds;
    }

    public static void main(String[] args) {
        UpperBoundCalculator calculator = new UpperBoundCalculator();
        List<Integer> keys = List.of(3, 1, 4, 1, 5, 9, 2, 6, 5, 3, 5);
        List<Integer> upperBounds = calculator.computeUpperBounds(keys);
        System.out.println(upperBounds);
    }
}

import java.net.URLEncoder;
import java.io.UnsupportedEncodingException;

public class TemplateEncoder {

    /**
     * Encodes a string with template parameters names present, specifically the characters '{' and '}' will be percent-encoded.
     * @param s the string with zero or more template parameters names
     * @return the string with encoded template parameters names.
     */
    public static String encodeTemplateNames(String s) {
        if (s == null) {
            return null;
        }
        try {
            return URLEncoder.encode(s, "UTF-8")
                    .replace("%7B", "{")
                    .replace("%7D", "}");
        } catch (UnsupportedEncodingException e) {
            throw new RuntimeException("UTF-8 encoding not supported", e);
        }
    }

    public static void main(String[] args) {
        // Example usage
        String input = "Hello {name}, welcome to {place}!";
        String encoded = encodeTemplateNames(input);
        System.out.println(encoded); // Output: Hello %7Bname%7D, welcome to %7Bplace%7D!
    }
}

import java.awt.geom.Point2D;

public class PointComparator {

    /**
     * Compare two points for equality using tolerance 1e-9.
     * @param p1 the first point
     * @param p2 the second point
     * @return whether the two points are equal or not
     */
    public static boolean equals(Point2D p1, Point2D p2) {
        if (p1 == null || p2 == null) {
            return false;
        }
        double tolerance = 1e-9;
        return Math.abs(p1.getX() - p2.getX()) < tolerance && Math.abs(p1.getY() - p2.getY()) < tolerance;
    }

    public static void main(String[] args) {
        Point2D point1 = new Point2D.Double(1.0, 2.0);
        Point2D point2 = new Point2D.Double(1.000000001, 2.000000001);
        Point2D point3 = new Point2D.Double(1.1, 2.1);

        System.out.println(equals(point1, point2)); // true
        System.out.println(equals(point1, point3)); // false
    }
}

