    }
}

import java.util.HashMap;
import java.util.Map;

class Node {
    private boolean isVirtual;
    private Node realCounterpart;

    public Node(boolean isVirtual, Node realCounterpart) {
        this.isVirtual = isVirtual;
        this.realCounterpart = realCounterpart;
    }

    public boolean isVirtual() {
        return isVirtual;
    }

    public Node getRealCounterpart() {
        return realCounterpart;
    }
}

class Edge {
    private Node from;
    private Node to;

    public Edge(Node from, Node to) {
        this.from = from;
        this.to = to;
    }

    public Node getFrom() {
        return from;
    }

    public Node getTo() {
        return to;
    }
}

class Graph {
    private Map<Node, Node> nodeSequence;
    private Node currentNode;

    public Graph() {
        nodeSequence = new HashMap<>();
        currentNode = null;
    }

    public void addNode(Node node) {
        if (currentNode != null) {
            nodeSequence.put(currentNode, node);
        }
        currentNode = node;
    }

    public Edge edgeToNext() {
        if (currentNode == null) {
            throw new IllegalStateException("No nodes have been added to the graph.");
        }

        Node nextNode = nodeSequence.get(currentNode);
        if (nextNode == null) {
            throw new IllegalStateException("No next node available.");
        }

        Node fromNode = currentNode.isVirtual() ? currentNode.getRealCounterpart() : currentNode;
        Node toNode = nextNode.isVirtual() ? nextNode.getRealCounterpart() : nextNode;

        return new Edge(fromNode, toNode);
    }
}

public class Main {
    public static void main(String[] args) {
        Node node1 = new Node(false, null);
        Node node2 = new Node(true, new Node(false, null));
        Node node3 = new Node(false, null);

        Graph graph = new Graph();
        graph.addNode(node1);
        graph.addNode(node2);
        graph.addNode(node3);

        Edge edge = graph.edgeToNext();
        System.out.println("Edge from: " + edge.getFrom() + " to: " + edge.getTo());
    }
}

import java.lang.CharSequence;

public class SubstringMatcher {

    /**
     * Returns {@code true} if the given string matches the given substring at the given index, {@code false} otherwise.
     * @param str the original string (or StringBuilder)
     * @param index the index in the original string to start matching against
     * @param substring the substring to match at the given index
     * @return {@code true} if the given string matches the given substring at the given index, {@code false} otherwise.
     */
    public static boolean substringMatch(CharSequence str, int index, CharSequence substring) {
        if (str == null || substring == null) {
            return false;
        }

        if (index < 0 || index + substring.length() > str.length()) {
            return false;
        }

        for (int i = 0; i < substring.length(); i++) {
            if (str.charAt(index + i) != substring.charAt(i)) {
                return false;
            }
        }

        return true;
    }

    public static void main(String[] args) {
        // Test cases
        System.out.println(substringMatch("hello", 1, "ell")); // true
        System.out.println(substringMatch("hello", 2, "ll"));  // true
        System.out.println(substringMatch("hello", 0, "he"));  // true
        System.out.println(substringMatch("hello", 3, "lo"));  // true
        System.out.println(substringMatch("hello", 4, "o"));   // true
        System.out.println(substringMatch("hello", 5, ""));    // true
        System.out.println(substringMatch("hello", 1, "elo")); // false
        System.out.println(substringMatch("hello", 5, "o"));   // false
        System.out.println(substringMatch("hello", -1, "h"));  // false
        System.out.println(substringMatch("hello", 0, "hello world")); // false
    }
}

