import java.io.IOException;
import java.io.InputStream;

public class ProtocolMessageParser {

    private final InputStream inputStream;

    public ProtocolMessageParser(InputStream inputStream) {
        this.inputStream = inputStream;
    }

    /**
     * Attempt to read a field tag, returning zero if we have reached EOF. Protocol message parsers use this to read tags, since a protocol message may legally end wherever a tag occurs, and zero is not a valid tag number.
     */
    public int readTag() throws IOException {
        int firstByte = inputStream.read();
        if (firstByte == -1) {
            return 0; // EOF
        }

        int tag = firstByte;
        if ((firstByte & 0x80) == 0) {
            return tag;
        }

        int secondByte = inputStream.read();
        if (secondByte == -1) {
            throw new IOException("Invalid protocol buffer stream");
        }
        tag = (tag & 0x7F) | ((secondByte & 0x7F) << 7);
        if ((secondByte & 0x80) == 0) {
            return tag;
        }

        int thirdByte = inputStream.read();
        if (thirdByte == -1) {
            throw new IOException("Invalid protocol buffer stream");
        }
        tag = (tag & 0x3FFF) | ((thirdByte & 0x7F) << 14);
        if ((thirdByte & 0x80) == 0) {
            return tag;
        }

        int fourthByte = inputStream.read();
        if (fourthByte == -1) {
            throw new IOException("Invalid protocol buffer stream");
        }
        tag = (tag & 0x1FFFFF) | ((fourthByte & 0x7F) << 21);
        if ((fourthByte & 0x80) == 0) {
            return tag;
        }

        throw new IOException("Invalid protocol buffer stream");
    }

    public static void main(String[] args) {
        // Example usage
        try (InputStream inputStream = System.in) {
            ProtocolMessageParser parser = new ProtocolMessageParser(inputStream);
            int tag = parser.readTag();
            System.out.println("Read tag: " + tag);
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}

import java.util.ArrayList;
import java.util.List;

public class ByteVector {
    private List<Byte> bytes;

    public ByteVector() {
        this.bytes = new ArrayList<>();
    }

    /**
     * Puts two bytes into this byte vector. The byte vector is automatically enlarged if necessary.
     * @param byteValue1 a byte.
     * @param byteValue2 another byte.
     * @return this byte vector.
     */
    final ByteVector put11(final int byteValue1, final int byteValue2) {
        if (byteValue1 < -128 || byteValue1 > 127 || byteValue2 < -128 || byteValue2 > 127) {
            throw new IllegalArgumentException("Values must be within the byte range (-128 to 127)");
        }
        bytes.add((byte) byteValue1);
        bytes.add((byte) byteValue2);
        return this;
    }

    public byte[] toArray() {
        byte[] array = new byte[bytes.size()];
        for (int i = 0; i < bytes.size(); i++) {
            array[i] = bytes.get(i);
        }
        return array;
    }

    public static void main(String[] args) {
        ByteVector byteVector = new ByteVector();
        byteVector.put11(10, 20);
        byte[] result = byteVector.toArray();
        for (byte b : result) {
            System.out.print(b + " ");
        }
    }
}

