import java.io.BufferedReader;
import java.io.FileReader;
import java.io.IOException;
import java.util.ArrayList;
import java.util.List;

public class ThreadSnapshotParser {

    /**
     * load thread snapshots in appointing time range
     */
    public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
        List<ThreadSnapshot> snapshots = new ArrayList<>();
        try (BufferedReader br = new BufferedReader(new FileReader(file))) {
            String line;
            while ((line = br.readLine()) != null) {
                ThreadSnapshot snapshot = parseThreadSnapshot(line);
                if (isWithinTimeRanges(snapshot.getTime(), timeRanges)) {
                    snapshots.add(snapshot);
                }
            }
        }
        return snapshots;
    }

    private static ThreadSnapshot parseThreadSnapshot(String line) {
        // Assuming the line format is "time,threadId,threadName,stackTrace"
        String[] parts = line.split(",");
        long time = Long.parseLong(parts[0]);
        int threadId = Integer.parseInt(parts[1]);
        String threadName = parts[2];
        String stackTrace = parts[3];
        return new ThreadSnapshot(time, threadId, threadName, stackTrace);
    }

    private static boolean isWithinTimeRanges(long time, List<ProfileAnalyzeTimeRange> timeRanges) {
        for (ProfileAnalyzeTimeRange range : timeRanges) {
            if (time >= range.getStartTime() && time <= range.getEndTime()) {
                return true;
            }
        }
        return false;
    }
}

class ThreadSnapshot {
    private long time;
    private int threadId;
    private String threadName;
    private String stackTrace;

    public ThreadSnapshot(long time, int threadId, String threadName, String stackTrace) {
        this.time = time;
        this.threadId = threadId;
        this.threadName = threadName;
        this.stackTrace = stackTrace;
    }

    public long getTime() {
        return time;
    }
}

class ProfileAnalyzeTimeRange {
    private long startTime;
    private long endTime;

    public ProfileAnalyzeTimeRange(long startTime, long endTime) {
        this.startTime = startTime;
        this.endTime = endTime;
    }

    public long getStartTime() {
        return startTime;
    }

    public long getEndTime() {
        return endTime;
    }
}
